"use client";

import { addClassNamesToElement } from "@lexical/utils";
import type {
  DOMConversionMap,
  DOMConversionOutput,
  DOMExportOutput,
  EditorConfig,
  LexicalEditor,
  LexicalNode,
  LexicalUpdateJSON,
  NodeKey,
  SerializedLexicalNode,
  Spread,
} from "lexical";
import { DecoratorNode } from "lexical";
import type { JSX } from "react";
import { ExcalidrawComponent } from "../../../plugins/excalidraw/component";

export type ExcalidrawDimension = number | "inherit";

export type ExcalidrawAlignment = "left" | "center" | "right";

export type SerializedExcalidrawNode = Spread<
  {
    alignment?: ExcalidrawAlignment;
    data: string;
    height?: ExcalidrawDimension;
    width?: ExcalidrawDimension;
  },
  SerializedLexicalNode
>;

/** Attribute used for HTML round-trips of excalidraw scenes. */
export const EXCALIDRAW_DATA_ATTRIBUTE = "data-lexical-excalidraw-json";

const getExcalidrawAlignment = (domNode: HTMLElement): ExcalidrawAlignment => {
  const { marginLeft, marginRight } = domNode.style;

  if (marginLeft === "auto" && marginRight === "auto") {
    return "center";
  }

  if (marginLeft === "auto") {
    return "right";
  }

  return "left";
};

const convertExcalidrawElement = (
  domNode: HTMLElement
): DOMConversionOutput | null => {
  const data = domNode.getAttribute(EXCALIDRAW_DATA_ATTRIBUTE);
  if (!data) {
    return null;
  }

  return {
    node: $createExcalidrawNode({
      alignment: getExcalidrawAlignment(domNode),
      data,
    }),
  };
};

export interface ExcalidrawNodePayload {
  alignment?: ExcalidrawAlignment;
  data?: string;
  height?: ExcalidrawDimension;
  key?: NodeKey;
  width?: ExcalidrawDimension;
}

/**
 * Block-level decorator node that stores an excalidraw scene as serialized
 * JSON. The rendered drawing is embedded into `exportDOM` alongside the raw
 * data attribute so pasted HTML stays visible outside the editor and can be
 * re-imported as an editable drawing.
 */
export class ExcalidrawNode extends DecoratorNode<JSX.Element> {
  __alignment: ExcalidrawAlignment;
  __data: string;
  __height: ExcalidrawDimension;
  __width: ExcalidrawDimension;

  constructor(
    data = "[]",
    alignment: ExcalidrawAlignment = "left",
    width: ExcalidrawDimension = "inherit",
    height: ExcalidrawDimension = "inherit",
    key?: NodeKey
  ) {
    super(key);
    this.__data = data;
    this.__alignment = alignment;
    this.__width = width;
    this.__height = height;
  }

  static getType(): string {
    return "excalidraw";
  }

  static clone(node: ExcalidrawNode): ExcalidrawNode {
    return new ExcalidrawNode(
      node.__data,
      node.__alignment,
      node.__width,
      node.__height,
      node.__key
    );
  }

  static importDOM(): DOMConversionMap | null {
    return {
      span: (domNode: HTMLElement) => {
        if (!domNode.hasAttribute(EXCALIDRAW_DATA_ATTRIBUTE)) {
          return null;
        }

        return {
          conversion: convertExcalidrawElement,
          priority: 1,
        };
      },
    };
  }

  static importJSON(serializedNode: SerializedExcalidrawNode): ExcalidrawNode {
    return $createExcalidrawNode({
      alignment: serializedNode.alignment,
      data: serializedNode.data,
      height: serializedNode.height,
      width: serializedNode.width,
    }).updateFromJSON(serializedNode);
  }

  updateFromJSON(
    serializedNode: LexicalUpdateJSON<SerializedExcalidrawNode>
  ): this {
    return super
      .updateFromJSON(serializedNode)
      .setData(serializedNode.data ?? "[]")
      .setAlignment(serializedNode.alignment ?? "left")
      .setHeight(serializedNode.height ?? "inherit")
      .setWidth(serializedNode.width ?? "inherit");
  }

  exportJSON(): SerializedExcalidrawNode {
    return {
      ...super.exportJSON(),
      alignment: this.__alignment,
      data: this.__data,
      height: this.__height === "inherit" ? undefined : this.__height,
      type: "excalidraw",
      version: 1,
      width: this.__width === "inherit" ? undefined : this.__width,
    };
  }

  exportDOM(editor: LexicalEditor): DOMExportOutput {
    const element = document.createElement("span");
    element.style.display = "block";

    // Mirror ImageNode's export so both block types round-trip alignment.
    if (this.__alignment === "center") {
      element.style.marginLeft = "auto";
      element.style.marginRight = "auto";
    } else if (this.__alignment === "right") {
      element.style.marginLeft = "auto";
      element.style.marginRight = "0";
    }

    // Embed the currently rendered svg so exported/pasted HTML shows the
    // drawing even where excalidraw is unavailable.
    const content = editor.getElementByKey(this.getKey());
    const svg = content?.querySelector("svg");
    if (svg) {
      element.append(svg.cloneNode(true));
    }

    if (this.__width !== "inherit") {
      element.style.width = `${this.__width}px`;
    }

    if (this.__height !== "inherit") {
      element.style.height = `${this.__height}px`;
    }

    element.setAttribute(EXCALIDRAW_DATA_ATTRIBUTE, this.__data);
    return { element };
  }

  createDOM(config: EditorConfig): HTMLElement {
    const span = document.createElement("span");

    if (typeof config.theme.image === "string") {
      addClassNamesToElement(span, config.theme.image);
    }

    return span;
  }

  updateDOM(): false {
    return false;
  }

  decorate(): JSX.Element {
    return (
      <ExcalidrawComponent
        alignment={this.__alignment}
        data={this.__data}
        height={this.__height}
        nodeKey={this.getKey()}
        width={this.__width}
      />
    );
  }

  isInline(): false {
    return false;
  }

  getData(): string {
    return this.getLatest().__data;
  }

  getAlignment(): ExcalidrawAlignment {
    return this.getLatest().__alignment;
  }

  getWidth(): ExcalidrawDimension {
    return this.getLatest().__width;
  }

  getHeight(): ExcalidrawDimension {
    return this.getLatest().__height;
  }

  setData(data: string): this {
    const writable = this.getWritable();
    writable.__data = data;
    return writable;
  }

  setAlignment(alignment: ExcalidrawAlignment): this {
    const writable = this.getWritable();
    writable.__alignment = alignment;
    return writable;
  }

  setWidth(width: ExcalidrawDimension): this {
    const writable = this.getWritable();
    writable.__width = width;
    return writable;
  }

  setHeight(height: ExcalidrawDimension): this {
    const writable = this.getWritable();
    writable.__height = height;
    return writable;
  }
}

export function $createExcalidrawNode({
  alignment,
  data,
  height,
  key,
  width,
}: ExcalidrawNodePayload = {}): ExcalidrawNode {
  return new ExcalidrawNode(data, alignment, width, height, key);
}

export function $isExcalidrawNode(
  node: LexicalNode | null | undefined
): node is ExcalidrawNode {
  return node instanceof ExcalidrawNode;
}

"use client";

import { createCommand, type LexicalCommand } from "lexical";

export const INSERT_EXCALIDRAW_COMMAND: LexicalCommand<void> = createCommand(
  "INSERT_EXCALIDRAW_COMMAND"
);

"use client";

import { useLexicalComposerContext } from "@lexical/react/LexicalComposerContext";
import { useLexicalEditable } from "@lexical/react/useLexicalEditable";
import { useLexicalNodeSelection } from "@lexical/react/useLexicalNodeSelection";
import { mergeRegister } from "@lexical/utils";
import {
  $getNodeByKey,
  $getSelection,
  $isNodeSelection,
  CLICK_COMMAND,
  COMMAND_PRIORITY_LOW,
  DRAGSTART_COMMAND,
  FORMAT_ELEMENT_COMMAND,
  KEY_BACKSPACE_COMMAND,
  KEY_DELETE_COMMAND,
  type LexicalEditor,
  type NodeKey,
} from "lexical";
import { PencilIcon } from "lucide-react";
import type { RefObject } from "react";
import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import {
  $isExcalidrawNode,
  type ExcalidrawAlignment,
} from "../../core/nodes/excalidraw/node";
import { ImageResizer } from "../image/resizer";
import { ExcalidrawImage } from "./image";
import {
  ExcalidrawEditorDialog,
  type SaveExcalidrawScenePayload,
} from "./modal";
import {
  hasExcalidrawContent,
  parseExcalidrawScene,
  serializeExcalidrawScene,
} from "./scene";

interface ExcalidrawComponentProps {
  alignment: ExcalidrawAlignment;
  data: string;
  height: number | "inherit";
  nodeKey: NodeKey;
  width: number | "inherit";
}

interface SelectionBehaviorOptions {
  buttonRef: RefObject<HTMLButtonElement | null>;
  clearSelection: () => void;
  editable: boolean;
  isResizing: boolean;
  isSelected: boolean;
  nodeKey: NodeKey;
  openEditor: () => void;
  removeNode: () => void;
  setSelected: (selected: boolean) => void;
}

const isInsideButton = (
  button: HTMLButtonElement | null,
  target: EventTarget | null
): boolean => {
  return Boolean(button && target instanceof Node && button.contains(target));
};

/**
 * Wires click-to-select, double-click-to-edit, drag suppression, alignment
 * and delete-key removal for one drawing block.
 */
const useExcalidrawSelectionBehavior = ({
  buttonRef,
  clearSelection,
  editable,
  isResizing,
  isSelected,
  nodeKey,
  openEditor,
  removeNode,
  setSelected,
}: SelectionBehaviorOptions) => {
  const [editor] = useLexicalComposerContext();

  useEffect(() => {
    if (!editable) {
      if (isSelected) {
        clearSelection();
      }
      return;
    }

    const removeSelectedDrawing = (event: KeyboardEvent) => {
      const selection = $getSelection();
      if (!(isSelected && $isNodeSelection(selection))) {
        return false;
      }

      event.preventDefault();
      removeNode();
      return true;
    };

    return mergeRegister(
      editor.registerCommand(
        CLICK_COMMAND,
        (event) => {
          if (isResizing) {
            return true;
          }

          if (!isInsideButton(buttonRef.current, event.target)) {
            return false;
          }

          if (event.shiftKey) {
            setSelected(!isSelected);
          } else {
            clearSelection();
            setSelected(true);
          }

          if (event.detail > 1) {
            openEditor();
          }

          return true;
        },
        COMMAND_PRIORITY_LOW
      ),
      editor.registerCommand(
        DRAGSTART_COMMAND,
        (event) => {
          if (!isInsideButton(buttonRef.current, event.target)) {
            return false;
          }

          event.preventDefault();
          return true;
        },
        COMMAND_PRIORITY_LOW
      ),
      editor.registerCommand(
        FORMAT_ELEMENT_COMMAND,
        (format) => {
          if (!isSelected) {
            return false;
          }

          if (
            !(format === "left" || format === "center" || format === "right")
          ) {
            return false;
          }

          editor.update(() => {
            const node = $getNodeByKey(nodeKey);
            if ($isExcalidrawNode(node)) {
              node.setAlignment(format as ExcalidrawAlignment);
            }
          });

          return true;
        },
        COMMAND_PRIORITY_LOW
      ),
      editor.registerCommand(
        KEY_BACKSPACE_COMMAND,
        removeSelectedDrawing,
        COMMAND_PRIORITY_LOW
      ),
      editor.registerCommand(
        KEY_DELETE_COMMAND,
        removeSelectedDrawing,
        COMMAND_PRIORITY_LOW
      )
    );
  }, [
    buttonRef,
    clearSelection,
    editable,
    editor,
    isResizing,
    isSelected,
    nodeKey,
    openEditor,
    removeNode,
    setSelected,
  ]);
};

const applyDimensions = (
  editor: LexicalEditor,
  nodeKey: NodeKey,
  nextWidth: number | "inherit",
  nextHeight: number | "inherit"
) => {
  editor.update(() => {
    const node = $getNodeByKey(nodeKey);
    if ($isExcalidrawNode(node)) {
      node.setWidth(nextWidth);
      node.setHeight(nextHeight);
    }
  });
};

interface ExcalidrawPreviewProps {
  alignment: ExcalidrawAlignment;
  buttonRef: RefObject<HTMLButtonElement | null>;
  containerRef: RefObject<HTMLDivElement | null>;
  editable: boolean;
  editor: LexicalEditor;
  height: number | "inherit";
  isSelected: boolean;
  nodeKey: NodeKey;
  openEditor: () => void;
  scene: ReturnType<typeof parseExcalidrawScene>;
  setIsResizing: (isResizing: boolean) => void;
  width: number | "inherit";
}

function ExcalidrawPreview({
  alignment,
  buttonRef,
  containerRef,
  editable,
  editor,
  height,
  isSelected,
  nodeKey,
  openEditor,
  scene,
  setIsResizing,
  width,
}: ExcalidrawPreviewProps) {
  // Mirrors ImageComponent's wrappers so both block types align identically.
  let figureClassName = "my-4 w-fit max-w-full";
  let alignmentClassName = "inline-flex max-w-full";

  if (alignment === "center") {
    figureClassName = "my-4 w-full";
    alignmentClassName = "flex max-w-full justify-center";
  } else if (alignment === "right") {
    figureClassName = "my-4 ml-auto w-fit max-w-full";
    alignmentClassName = "flex max-w-full justify-end";
  }

  return (
    <figure className={figureClassName}>
      <div className={alignmentClassName}>
        <div className="relative inline-flex max-w-full">
          <div
            className={
              isSelected && editable
                ? "rounded-xl ring-1 ring-primary/40 ring-offset-2 ring-offset-background"
                : "rounded-xl"
            }
          >
            <button
              aria-label="Drawing preview, double-click to edit"
              className="block cursor-default overflow-hidden rounded-lg border border-border/60 bg-muted/20 shadow-xs"
              ref={buttonRef}
              type="button"
            >
              <ExcalidrawImage
                appState={scene.appState}
                containerRef={containerRef}
                elements={scene.elements}
                files={scene.files}
                height={height}
                width={width}
              />
            </button>
          </div>

          {/*
           * The edit button lives inside the resizer's bounds-synced overlay so
           * it hugs the handles at the drawing's true top-right corner. Anchoring
           * it to this container instead would let it drift away whenever the
           * committed width exceeds the clamped container (`max-w-full`).
           */}
          {editable && isSelected ? (
            <ImageResizer
              decorations={
                <button
                  aria-label="Edit drawing"
                  className="absolute -top-3 right-2 z-10 flex size-6 items-center justify-center rounded-md bg-popover shadow-lg ring-1 ring-border transition-colors hover:bg-accent"
                  onClick={(event) => {
                    event.stopPropagation();
                    openEditor();
                  }}
                  onMouseDown={(event) => {
                    event.preventDefault();
                  }}
                  type="button"
                >
                  <PencilIcon className="size-3 text-muted-foreground" />
                </button>
              }
              edgeHandles
              editor={editor}
              imageRef={containerRef}
              onResizeEnd={(nextWidth, nextHeight) => {
                window.setTimeout(() => {
                  setIsResizing(false);
                }, 200);

                applyDimensions(editor, nodeKey, nextWidth, nextHeight);
              }}
              onResizeStart={() => {
                setIsResizing(true);
              }}
            />
          ) : null}
        </div>
      </div>
    </figure>
  );
}

export function ExcalidrawComponent({
  alignment,
  data,
  height,
  nodeKey,
  width,
}: ExcalidrawComponentProps) {
  const [editor] = useLexicalComposerContext();
  const editable = useLexicalEditable();
  const [isSelected, setSelected, clearSelection] =
    useLexicalNodeSelection(nodeKey);
  const [isResizing, setIsResizing] = useState(false);

  const scene = useMemo(() => parseExcalidrawScene(data), [data]);
  // A drawing inserted through the slash menu, toolbar insert or the plugin
  // command starts empty and opens its editing surface right away.
  const [isEditorOpen, setIsEditorOpen] = useState(
    () => scene.elements.length === 0 && editable
  );
  const wasEmptyOnMountRef = useRef(scene.elements.length === 0);
  const containerRef = useRef<HTMLDivElement | null>(null);
  const buttonRef = useRef<HTMLButtonElement | null>(null);

  const removeNode = useCallback(() => {
    return editor.update(() => {
      const node = $getNodeByKey(nodeKey);
      if ($isExcalidrawNode(node)) {
        node.remove();
      }
    });
  }, [editor, nodeKey]);

  const openEditor = useCallback(() => {
    setIsEditorOpen(true);
  }, []);

  useExcalidrawSelectionBehavior({
    buttonRef,
    clearSelection,
    editable,
    isResizing,
    isSelected,
    nodeKey,
    openEditor,
    removeNode,
    setSelected,
  });

  useEffect(() => {
    return () => {
      document.body.style.removeProperty("cursor");
      document.body.style.removeProperty("-webkit-user-select");
      document.body.style.removeProperty("user-select");
    };
  }, []);

  if (!editable && scene.elements.length === 0) {
    return null;
  }

  const handleCloseEditor = () => {
    setIsEditorOpen(false);

    if (wasEmptyOnMountRef.current && !hasExcalidrawContent(scene)) {
      removeNode();
    }
  };

  const handleSaveEditor = (payload: SaveExcalidrawScenePayload) => {
    const { appState, elements, files } = payload;
    setIsEditorOpen(false);

    editor.update(() => {
      const node = $getNodeByKey(nodeKey);
      if (!$isExcalidrawNode(node)) {
        return;
      }

      if (hasExcalidrawContent({ elements, files })) {
        node.setData(serializeExcalidrawScene(elements, appState, files));
        return;
      }

      node.remove();
    });
  };

  return (
    <>
      {isEditorOpen ? (
        <ExcalidrawEditorDialog
          initialScene={scene}
          onClose={handleCloseEditor}
          onSave={handleSaveEditor}
        />
      ) : null}

      {scene.elements.length > 0 ? (
        <ExcalidrawPreview
          alignment={alignment}
          buttonRef={buttonRef}
          containerRef={containerRef}
          editable={editable}
          editor={editor}
          height={height}
          isSelected={isSelected}
          nodeKey={nodeKey}
          openEditor={openEditor}
          scene={scene}
          setIsResizing={setIsResizing}
          width={width}
        />
      ) : null}
    </>
  );
}

import { $createParagraphNode, type ElementNode } from "lexical";
import { PencilRulerIcon } from "lucide-react";
import {
  $createExcalidrawNode,
  ExcalidrawNode,
} from "../../core/nodes/excalidraw/node";
import type { ExtraEditorFeature } from "../../core/types";
import { replaceCurrentBlock } from "../slash-command/utils";
import { ExcalidrawPlugin } from "./plugin";

// Replacing the selected paragraph leaves the selection dangling, which rolls
// the whole update back — re-anchor it on a trailing paragraph. The empty
// drawing block opens its editing surface as soon as it renders; discarding
// removes the node and keeps the paragraph.
const applyExcalidrawCommand = (targetElement: ElementNode): void => {
  const excalidrawNode = $createExcalidrawNode();
  const paragraph = $createParagraphNode();

  targetElement.replace(excalidrawNode);
  excalidrawNode.insertAfter(paragraph);
  paragraph.select();
};

/**
 * Installs the drawing feature: the `ExcalidrawNode`, its editing surface and
 * the shared insert-menu entry. Ships as the `editor-excalidraw` registry
 * item and pulls `@excalidraw/excalidraw`.
 */
export const excalidrawFeature: ExtraEditorFeature = {
  id: "excalidraw",
  nodes: [ExcalidrawNode],
  plugin: ExcalidrawPlugin,
  slashCommands: [
    {
      command: {
        description: "Draw a diagram or sketch",
        icon: PencilRulerIcon,
        id: "excalidraw",
        keywords: ["drawing", "diagram", "sketch", "whiteboard", "canvas"],
        label: "Drawing",
      },
      run: (editor) => {
        replaceCurrentBlock(editor, applyExcalidrawCommand);
      },
    },
  ],
};

"use client";

import type {
  ExcalidrawElement,
  NonDeleted,
} from "@excalidraw/excalidraw/element/types";
import type { AppState, BinaryFiles } from "@excalidraw/excalidraw/types";
import { useEffect, useRef, useState } from "react";

interface ExcalidrawImageProps {
  appState?: Partial<AppState>;
  containerRef?: { current: HTMLDivElement | null };
  elements: readonly NonDeleted<ExcalidrawElement>[];
  files?: BinaryFiles;
  height: number | "inherit";
  width: number | "inherit";
}

/**
 * Appends an excalidraw-produced svg element to the DOM. The element is built
 * imperatively by excalidraw's export runtime, so it is attached outside of
 * React's ownership model instead of serialized into markup. The wrapper is
 * the direct child of the sized container and must forward its height so
 * `height: 100%` on the svg reaches the container's explicit box.
 */
function SvgHost({ svg }: { svg: SVGSVGElement }) {
  return (
    <div
      className="h-full w-full"
      ref={(node) => {
        if (node?.firstElementChild !== svg) {
          node?.replaceChildren(svg);
        }
      }}
    />
  );
}

/**
 * Renders an excalidraw scene as a static svg image. The heavy `exportToSvg`
 * runtime is loaded on demand so documents without drawings never pay for it.
 */
export function ExcalidrawImage({
  appState,
  containerRef,
  elements,
  files,
  height,
  width,
}: ExcalidrawImageProps) {
  const [svg, setSvg] = useState<SVGSVGElement | null>(null);
  const boxRef = useRef<HTMLDivElement | null>(null);
  // The drawing fills its box (free resize) whenever both axes carry explicit
  // dimensions; otherwise it keeps the viewBox aspect ratio and drives its
  // own height. Initialized from the committed props so SSR-safe renders
  // match, then kept in sync with the box's live inline styles.
  const [fillsBox, setFillsBox] = useState(
    width !== "inherit" && height !== "inherit"
  );

  // A resize drag styles the box imperatively every frame, long before the
  // node commit updates `width`/`height` props. Observing the box keeps the
  // svg stretching in real time so handles never detach mid-drag.
  useEffect(() => {
    const box = boxRef.current;
    if (!box || typeof ResizeObserver === "undefined") {
      return;
    }

    const syncFillMode = () => {
      setFillsBox(box.style.width !== "" && box.style.height !== "");
    };

    const observer = new ResizeObserver(syncFillMode);
    observer.observe(box);
    syncFillMode();
    return () => observer.disconnect();
  }, []);

  useEffect(() => {
    let cancelled = false;

    const renderScene = async () => {
      const { exportToSvg } = await import("@excalidraw/excalidraw");
      const nextSvg = await exportToSvg({
        appState,
        elements: [...elements],
        files: files ?? null,
      });

      // Generated svgs carry fixed pixel dimensions; strip them so the
      // sizing effect below fully controls the fluid box.
      nextSvg.removeAttribute("width");
      nextSvg.removeAttribute("height");

      if (!cancelled) {
        setSvg(nextSvg);
      }
    };

    renderScene().catch(() => undefined);

    return () => {
      cancelled = true;
    };
  }, [appState, elements, files]);

  useEffect(() => {
    if (!svg) {
      return;
    }

    svg.style.display = "block";
    svg.style.width = "100%";

    if (fillsBox) {
      // Fill the resized box; corners stay glued to the drawing.
      svg.style.height = "100%";
      svg.setAttribute("preserveAspectRatio", "none");
      return;
    }

    // Keep the viewBox aspect ratio and drive the container height.
    svg.style.height = "auto";
    svg.setAttribute("preserveAspectRatio", "xMidYMid meet");
  }, [fillsBox, svg]);

  const style: React.CSSProperties = {};
  if (width !== "inherit") {
    style.width = `${width}px`;
  }
  if (height !== "inherit") {
    style.height = `${height}px`;
  }

  return (
    <div
      className="max-w-full"
      ref={(node) => {
        boxRef.current = node;
        if (containerRef && node) {
          containerRef.current = node;
        }
      }}
      style={style}
    >
      {svg ? <SvgHost svg={svg} /> : null}
    </div>
  );
}

"use client";

import type {
  AppState,
  BinaryFiles,
  ExcalidrawImperativeAPI,
  ExcalidrawProps,
} from "@excalidraw/excalidraw/types";
import { XIcon } from "lucide-react";
import { lazy, Suspense, useEffect, useRef, useState } from "react";
import { Button } from "@/components/ui/button";
import type {
  ExcalidrawInitialElements,
  ExcalidrawScene,
  SaveableExcalidrawScene,
} from "./scene";
import { hasExcalidrawContent } from "./scene";

// The excalidraw runtime (component, styles and fonts) is loaded on demand:
// documents without drawings never download it.
const loadExcalidrawEditor = async (): Promise<{
  default: React.ComponentType<ExcalidrawProps>;
}> => {
  await import("@excalidraw/excalidraw/index.css");
  const { Excalidraw } = await import("@excalidraw/excalidraw");
  return {
    default: Excalidraw as unknown as React.ComponentType<ExcalidrawProps>,
  };
};

const LazyExcalidrawEditor = lazy(loadExcalidrawEditor);

export interface SaveExcalidrawScenePayload {
  appState: Partial<AppState>;
  elements: ExcalidrawInitialElements;
  files: BinaryFiles;
}

interface ExcalidrawEditorDialogProps {
  /** Scene shown when the editor opens. */
  initialScene: ExcalidrawScene;
  onClose: () => void;
  onSave: (payload: SaveExcalidrawScenePayload) => void;
}

/** Only the app state pieces worth persisting alongside a drawing. */
const pickPersistedAppState = (appState: AppState): Partial<AppState> => ({
  exportBackground: appState.exportBackground,
  exportScale: appState.exportScale,
  exportWithDarkMode: appState.theme === "dark",
  isBindingEnabled: appState.isBindingEnabled,
  name: appState.name,
  theme: appState.theme,
  viewBackgroundColor: appState.viewBackgroundColor,
  viewModeEnabled: appState.viewModeEnabled,
  zenModeEnabled: appState.zenModeEnabled,
});

/**
 * Full-screen editing surface for a single excalidraw scene. Saving hands the
 * current elements back to the caller; closing discards local edits.
 */
export function ExcalidrawEditorDialog({
  initialScene,
  onClose,
  onSave,
}: ExcalidrawEditorDialogProps) {
  const [api, setApi] = useState<ExcalidrawImperativeAPI | null>(null);
  const [isDiscardConfirmOpen, setIsDiscardConfirmOpen] = useState(false);
  const dialogRef = useRef<HTMLDivElement | null>(null);
  const latestSceneRef = useRef<SaveableExcalidrawScene>({
    elements: initialScene.elements,
    files: initialScene.files ?? {},
  });

  useEffect(() => {
    // Focus the dialog wrapper so Escape reaches it before the canvas takes
    // over keyboard handling.
    dialogRef.current?.focus();
  }, []);

  const hasUnsavedContent = () => {
    return hasExcalidrawContent(latestSceneRef.current);
  };

  const requestClose = () => {
    if (hasUnsavedContent()) {
      setIsDiscardConfirmOpen(true);
      return;
    }

    onClose();
  };

  const handleSave = () => {
    const appState = api?.getAppState();
    onSave({
      appState: appState ? pickPersistedAppState(appState) : {},
      elements: latestSceneRef.current.elements,
      files: latestSceneRef.current.files ?? {},
    });
  };

  return (
    // biome-ignore lint/a11y/noNoninteractiveElementInteractions: full-screen dialog wrapper captures Escape before page handlers
    <div
      aria-label="Excalidraw drawing editor"
      aria-modal="true"
      className="fixed inset-0 z-50 flex flex-col bg-background outline-none"
      onKeyDown={(event) => {
        // Only capture Escape before it reaches the page; the canvas keeps
        // its own Escape semantics (e.g. exiting zen mode).
        if (
          event.key === "Escape" &&
          !isDiscardConfirmOpen &&
          event.target === dialogRef.current
        ) {
          requestClose();
        }
      }}
      ref={dialogRef}
      role="dialog"
      tabIndex={-1}
    >
      <header className="flex items-center justify-between border-b px-4 py-2">
        <p className="font-medium text-sm">Excalidraw drawing</p>
        <div className="flex items-center gap-2">
          <Button onClick={requestClose} size="sm" variant="ghost">
            Discard
          </Button>
          <Button onClick={handleSave} size="sm">
            Save &amp; insert
          </Button>
          <Button
            aria-label="Close drawing editor"
            onClick={requestClose}
            size="icon-sm"
            variant="ghost"
          >
            <XIcon />
          </Button>
        </div>
      </header>

      <div className="relative min-h-0 flex-1">
        <Suspense
          fallback={
            <div className="flex h-full items-center justify-center text-muted-foreground text-sm">
              Loading drawing canvas…
            </div>
          }
        >
          <LazyExcalidrawEditor
            excalidrawAPI={setApi}
            initialData={{
              appState: initialScene.appState ?? {},
              elements: initialScene.elements,
              files: initialScene.files ?? {},
            }}
            onChange={(elements, _appState, files) => {
              latestSceneRef.current = { elements, files };
            }}
          />
        </Suspense>

        {isDiscardConfirmOpen ? (
          <div className="absolute inset-0 z-10 flex items-center justify-center bg-background/80 backdrop-blur-xs">
            <div
              aria-label="Discard changes"
              className="w-80 rounded-xl bg-popover p-4 shadow-lg ring-1 ring-border"
              role="alertdialog"
            >
              <p className="font-medium">Discard changes?</p>
              <p className="mt-1 text-muted-foreground text-sm">
                Your drawing has unsaved edits that will be lost.
              </p>
              <div className="mt-4 flex justify-end gap-2">
                <Button
                  onClick={() => {
                    setIsDiscardConfirmOpen(false);
                  }}
                  size="sm"
                  variant="outline"
                >
                  Keep editing
                </Button>
                <Button
                  onClick={() => {
                    setIsDiscardConfirmOpen(false);
                    onClose();
                  }}
                  size="sm"
                  variant="destructive"
                >
                  Discard
                </Button>
              </div>
            </div>
          </div>
        ) : null}
      </div>
    </div>
  );
}

"use client";

import { useLexicalComposerContext } from "@lexical/react/LexicalComposerContext";
import { $insertNodeToNearestRoot } from "@lexical/utils";
import { $createParagraphNode, COMMAND_PRIORITY_EDITOR } from "lexical";
import { useEffect } from "react";
import {
  $createExcalidrawNode,
  ExcalidrawNode,
} from "../../core/nodes/excalidraw/node";
import { INSERT_EXCALIDRAW_COMMAND } from "./commands";

/**
 * Mounts the excalidraw insert behavior. Dispatching
 * `INSERT_EXCALIDRAW_COMMAND` inserts an empty drawing block whose editing
 * surface opens immediately; slash commands and toolbar inserts share this
 * single path.
 */
export function ExcalidrawPlugin(): null {
  const [editor] = useLexicalComposerContext();

  useEffect(() => {
    if (!editor.hasNodes([ExcalidrawNode])) {
      throw new Error(
        "ExcalidrawPlugin: ExcalidrawNode is not registered on the editor"
      );
    }

    return editor.registerCommand(
      INSERT_EXCALIDRAW_COMMAND,
      () => {
        editor.update(() => {
          const excalidrawNode = $createExcalidrawNode();
          $insertNodeToNearestRoot(excalidrawNode);

          // Re-anchor the selection on a trailing paragraph so the update
          // never commits with a dangling selection.
          const paragraph = $createParagraphNode();
          excalidrawNode.insertAfter(paragraph);
          paragraph.select();
        });
        return true;
      },
      COMMAND_PRIORITY_EDITOR
    );
  }, [editor]);

  return null;
}

import type {
  ExcalidrawElement,
  NonDeleted,
} from "@excalidraw/excalidraw/element/types";
import type {
  AppState,
  BinaryFiles,
  ExcalidrawInitialDataState,
} from "@excalidraw/excalidraw/types";

export type ExcalidrawInitialElements = ExcalidrawInitialDataState["elements"];

/**
 * The subset of excalidraw state persisted inside an ExcalidrawNode. Only the
 * pieces needed to re-open and re-render a drawing are kept, mirroring what
 * the Lexical playground stores.
 */
export interface ExcalidrawScene {
  appState?: Partial<AppState>;
  elements: NonDeleted<ExcalidrawElement>[];
  files?: BinaryFiles;
}

/**
 * The live scene handed back by the excalidraw editor while drawing; element
 * lists are readonly and may be absent until the first change.
 */
export interface SaveableExcalidrawScene {
  appState?: Partial<AppState>;
  elements?: ExcalidrawInitialElements;
  files?: BinaryFiles;
}

const EMPTY_SCENE: ExcalidrawScene = { elements: [] };

export const EMPTY_SCENE_JSON = JSON.stringify(EMPTY_SCENE.elements);

export const serializeExcalidrawScene = (
  elements: ExcalidrawInitialElements,
  appState: Partial<AppState>,
  files: BinaryFiles
): string => {
  return JSON.stringify({ appState, elements, files });
};
export const parseExcalidrawScene = (data: string): ExcalidrawScene => {
  try {
    const parsed: unknown = JSON.parse(data);
    if (
      typeof parsed !== "object" ||
      parsed === null ||
      !Array.isArray((parsed as ExcalidrawScene).elements)
    ) {
      return EMPTY_SCENE;
    }

    const scene = parsed as ExcalidrawScene;
    return {
      appState: scene.appState,
      elements: scene.elements,
      files: scene.files ?? {},
    };
  } catch {
    return EMPTY_SCENE;
  }
};

export const hasExcalidrawContent = (
  scene: ExcalidrawScene | SaveableExcalidrawScene
): boolean => {
  const elements = scene.elements ?? [];
  return (
    elements.some((element) => !element.isDeleted) ||
    Object.keys(scene.files ?? {}).length > 0
  );
};
